   422→// reaggregateFromEntries reads all session metadata from the entries map and
   423→// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
   424→func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
   425→	var totalCount int
   426→	var allFiles []string
   427→	var totalTokens *agent.TokenUsage
   428→
   429→	for i := range sessionCount {
   430→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
   431→		entry, exists := entries[path]
   432→		if !exists {
   433→			return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
   434→		}
   435→		meta, err := s.readMetadataFromBlob(entry.Hash)
   436→		if err != nil {
   437→			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
   438→		}
   439→		totalCount += meta.CheckpointsCount
   440→		allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
   441→		totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
   442→	}
   443→
   444→	return totalCount, allFiles, totalTokens, nil
   445→}
