   447→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
   448→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
   449→	blob, err := repo.BlobObject(hash)
   450→	if err != nil {
   451→		return nil, fmt.Errorf("failed to get blob: %w", err)
   452→	}
   453→
   454→	reader, err := blob.Reader()
   455→	if err != nil {
   456→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   457→	}
   458→	defer reader.Close()
   459→
   460→	var result T
   461→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
   462→		return nil, fmt.Errorf("failed to decode: %w", err)
   463→	}
   464→
   465→	return &result, nil
   466→}
