   473→// aggregateTokenUsage sums two TokenUsage structs.
   474→// Returns nil if both inputs are nil.
   475→func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
   476→	if a == nil && b == nil {
   477→		return nil
   478→	}
   479→	result := &agent.TokenUsage{}
   480→	if a != nil {
   481→		result.InputTokens = a.InputTokens
   482→		result.CacheCreationTokens = a.CacheCreationTokens
   483→		result.CacheReadTokens = a.CacheReadTokens
   484→		result.OutputTokens = a.OutputTokens
   485→		result.APICallCount = a.APICallCount
   486→	}
   487→	if b != nil {
   488→		result.InputTokens += b.InputTokens
   489→		result.CacheCreationTokens += b.CacheCreationTokens
   490→		result.CacheReadTokens += b.CacheReadTokens
   491→		result.OutputTokens += b.OutputTokens
   492→		result.APICallCount += b.APICallCount
   493→	}
   494→	return result
   495→}
