   497→// writeTranscript writes the transcript file from in-memory content or file path.
   498→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
   499→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   500→	transcript := opts.Transcript
   501→	if len(transcript) == 0 && opts.TranscriptPath != "" {
   502→		var readErr error
   503→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
   504→		if readErr != nil {
   505→			// Non-fatal: transcript may not exist yet
   506→			transcript = nil
   507→		}
   508→	}
   509→	if len(transcript) == 0 {
   510→		return nil
   511→	}
   512→
   513→	// Redact secrets before chunking so content hash reflects redacted content
   514→	transcript, err := redact.JSONLBytes(transcript)
   515→	if err != nil {
   516→		return fmt.Errorf("failed to redact transcript secrets: %w", err)
   517→	}
   518→
   519→	// Chunk the transcript if it's too large
   520→	chunks, err := agent.ChunkTranscript(transcript, opts.Agent)
   521→	if err != nil {
   522→		return fmt.Errorf("failed to chunk transcript: %w", err)
   523→	}
   524→
   525→	// Write chunk files
   526→	for i, chunk := range chunks {
   527→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
   528→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
   529→		if err != nil {
   530→			return err
   531→		}
   532→		entries[chunkPath] = object.TreeEntry{
   533→			Name: chunkPath,
   534→			Mode: filemode.Regular,
   535→			Hash: blobHash,
   536→		}
   537→	}
   538→
   539→	// Content hash for deduplication (hash of full transcript)
   540→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
   541→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   542→	if err != nil {
   543→		return err
   544→	}
   545→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
   546→		Name: basePath + paths.ContentHashFileName,
   547→		Mode: filemode.Regular,
   548→		Hash: hashBlob,
   549→	}
   550→	return nil
   551→}
