   553→// mergeFilesTouched combines two file lists, removing duplicates.
   554→func mergeFilesTouched(existing, additional []string) []string {
   555→	seen := make(map[string]bool)
   556→	var result []string
   557→
   558→	for _, f := range existing {
   559→		if !seen[f] {
   560→			seen[f] = true
   561→			result = append(result, f)
   562→		}
   563→	}
   564→	for _, f := range additional {
   565→		if !seen[f] {
   566→			seen[f] = true
   567→			result = append(result, f)
   568→		}
   569→	}
   570→
   571→	sort.Strings(result)
   572→	return result
   573→}
