   580→// buildCommitMessage constructs the commit message with proper trailers.
   581→// The commit subject is always "Checkpoint: <id>" for consistency.
   582→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   583→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   584→	var commitMsg strings.Builder
   585→
   586→	// Subject line is always the checkpoint ID for consistent formatting
   587→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   588→
   589→	// Include custom description in body if provided (e.g., task checkpoint details)
   590→	if opts.CommitSubject != "" {
   591→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   592→	}
   593→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
   594→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
   595→	if opts.Agent != "" {
   596→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
   597→	}
   598→	if opts.EphemeralBranch != "" {
