   630→//
   631→// The storage format uses numbered subdirectories for each session (0-based):
   632→//
   633→//	<checkpoint-id>/
   634→//	├── metadata.json      # CheckpointSummary with sessions map
   635→//	├── 0/                 # First session
   636→//	│   ├── metadata.json  # Session-specific metadata
   637→//	│   └── full.jsonl     # Transcript
   638→//	├── 1/                 # Second session
   639→//	└── ...
   640→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
   641→	_ = ctx // Reserved for future use
   642→
   643→	tree, err := s.getSessionsBranchTree()
   644→	if err != nil {
   645→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   646→	}
