   649→	checkpointTree, err := tree.Tree(checkpointPath)
   650→	if err != nil {
   651→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   652→	}
   653→
   654→	// Read root metadata.json as CheckpointSummary
   655→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
   656→	if err != nil {
   657→		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
   658→	}
