   673→// ReadSessionContent reads the actual content for a specific session within a checkpoint.
   674→// sessionIndex is 0-based (0 for first session, 1 for second, etc.).
   675→// Returns the session's metadata, transcript, prompts, and context.
   676→// Returns an error if the checkpoint or session doesn't exist.
   677→func (s *GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
   678→	_ = ctx // Reserved for future use
   679→
   680→	tree, err := s.getSessionsBranchTree()
   681→	if err != nil {
   682→		return nil, ErrCheckpointNotFound
   683→	}
   684→
   685→	checkpointPath := checkpointID.Path()
   686→	checkpointTree, err := tree.Tree(checkpointPath)
   687→	if err != nil {
   688→		return nil, ErrCheckpointNotFound
   689→	}
   690→
   691→	// Get the session subdirectory
   692→	sessionDir := strconv.Itoa(sessionIndex)
   693→	sessionTree, err := checkpointTree.Tree(sessionDir)
   694→	if err != nil {
   695→		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
   696→	}
   697→
   698→	result := &SessionContent{}
   699→
   700→	// Read session-specific metadata
   701→	var agentType agent.AgentType
   702→	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
   703→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   704→			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr == nil {
   705→				agentType = result.Metadata.Agent
   706→			}
   707→		}
   708→	}
   709→
   710→	// Read transcript
   711→	if transcript, transcriptErr := readTranscriptFromTree(sessionTree, agentType); transcriptErr == nil && transcript != nil {
   712→		result.Transcript = transcript
   713→	}
   714→
   715→	// Read prompts
   716→	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
   717→		if content, contentErr := file.Contents(); contentErr == nil {
   718→			result.Prompts = content
   719→		}
   720→	}
   721→
   722→	// Read context
   723→	if file, fileErr := sessionTree.File(paths.ContextFileName); fileErr == nil {
   724→		if content, contentErr := file.Contents(); contentErr == nil {
   725→			result.Context = content
   726→		}
   727→	}
   728→
   729→	return result, nil
   730→}
