   752→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   753→// Returns an error if no session with the given ID exists in the checkpoint.
   754→func (s *GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
   755→	summary, err := s.ReadCommitted(ctx, checkpointID)
   756→	if err != nil {
