   758→	}
   759→	if summary == nil {
   760→		return nil, ErrCheckpointNotFound
   761→	}
   762→
   763→	// Iterate through sessions to find the one with matching session ID
   764→	for i := range len(summary.Sessions) {
   765→		content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
   766→		if readErr != nil {
   767→			continue
   768→		}
   769→		if content != nil && content.Metadata.SessionID == sessionID {
   770→			return content, nil
   771→		}
   772→	}
   773→
   774→	return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
