   777→// ListCommitted lists all committed checkpoints from the entire/checkpoints/v1 branch.
   778→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   779→//
   780→
   781→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   782→	_ = ctx // Reserved for future use
   783→
   784→	tree, err := s.getSessionsBranchTree()
   785→	if err != nil {
   786→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   787→	}
   788→
   789→	var checkpoints []CommittedInfo
   790→
   791→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   792→	for _, bucketEntry := range tree.Entries {
   793→		if bucketEntry.Mode != filemode.Dir {
   794→			continue
   795→		}
   796→		// Bucket should be 2 hex chars
   797→		if len(bucketEntry.Name) != 2 {
   798→			continue
   799→		}
   800→
   801→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   802→		if treeErr != nil {
   803→			continue
   804→		}
   805→
   806→		// Each entry in the bucket is the remaining part of the checkpoint ID
   807→		for _, checkpointEntry := range bucketTree.Entries {
   808→			if checkpointEntry.Mode != filemode.Dir {
   809→				continue
   810→			}
   811→
   812→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   813→			if cpTreeErr != nil {
   814→				continue
   815→			}
   816→
   817→			// Reconstruct checkpoint ID: <bucket><remaining>
   818→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   819→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   820→			if cpIDErr != nil {
   821→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   822→				continue
   823→			}
   824→
   825→			info := CommittedInfo{
   826→				CheckpointID: checkpointID,
   827→			}
   828→
   829→			// Get details from root metadata file (CheckpointSummary format)
   830→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   831→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   832→					var summary CheckpointSummary
   833→					if err := json.Unmarshal([]byte(content), &summary); err == nil {
   834→						info.CheckpointsCount = summary.CheckpointsCount
   835→						info.FilesTouched = summary.FilesTouched
   836→						info.SessionCount = len(summary.Sessions)
   837→
   838→						// Read session metadata from latest session to get Agent, SessionID, CreatedAt
   839→						if len(summary.Sessions) > 0 {
   840→							latestIndex := len(summary.Sessions) - 1
   841→							latestDir := strconv.Itoa(latestIndex)
   842→							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
   843→								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
   844→									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
   845→										var sessionMetadata CommittedMetadata
   846→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   847→											info.Agent = sessionMetadata.Agent
   848→											info.SessionID = sessionMetadata.SessionID
   849→											info.CreatedAt = sessionMetadata.CreatedAt
   850→										}
   851→									}
   852→								}
   853→							}
   854→						}
   855→					}
   856→				}
   857→			}
   858→
   859→			checkpoints = append(checkpoints, info)
   860→		}
   861→	}
   862→
   863→	// Sort by time (most recent first)
   864→	sort.Slice(checkpoints, func(i, j int) bool {
   865→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   866→	})
   867→
   868→	return checkpoints, nil
   869→}
