   916→// UpdateSummary updates the summary field in the latest session's metadata.
   917→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   918→func (s *GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
   919→	_ = ctx // Reserved for future use
   920→
   921→	// Ensure sessions branch exists
   922→	if err := s.ensureSessionsBranch(); err != nil {
   923→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
   924→	}
   925→
   926→	// Get current branch tip and flatten tree
   927→	ref, entries, err := s.getSessionsBranchEntries()
   928→	if err != nil {
   929→		return err
   930→	}
   931→
   932→	// Read root CheckpointSummary to find the latest session
   933→	basePath := checkpointID.Path() + "/"
   934→	rootMetadataPath := basePath + paths.MetadataFileName
   935→	entry, exists := entries[rootMetadataPath]
   936→	if !exists {
   937→		return ErrCheckpointNotFound
   938→	}
   939→
   940→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
   941→	if err != nil {
   942→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
   943→	}
   944→
   945→	// Find the latest session's metadata path (0-based indexing)
   946→	latestIndex := len(checkpointSummary.Sessions) - 1
   947→	sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
   948→	sessionEntry, exists := entries[sessionMetadataPath]
   949→	if !exists {
   950→		return fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
   951→	}
   952→
   953→	// Read and update session metadata
   954→	existingMetadata, err := s.readMetadataFromBlob(sessionEntry.Hash)
   955→	if err != nil {
   956→		return fmt.Errorf("failed to read session metadata: %w", err)
   957→	}
   958→
   959→	// Update the summary
   960→	existingMetadata.Summary = summary
   961→
   962→	// Write updated session metadata
   963→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
   964→	if err != nil {
   965→		return fmt.Errorf("failed to marshal metadata: %w", err)
   966→	}
   967→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   968→	if err != nil {
   969→		return fmt.Errorf("failed to create metadata blob: %w", err)
   970→	}
   971→	entries[sessionMetadataPath] = object.TreeEntry{
   972→		Name: sessionMetadataPath,
   973→		Mode: filemode.Regular,
   974→		Hash: metadataHash,
   975→	}
   976→
   977→	// Build and commit
   978→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
   979→	if err != nil {
   980→		return err
   981→	}
   982→
   983→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
   984→	commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, existingMetadata.SessionID)
   985→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
   986→	if err != nil {
   987→		return err
   988→	}
   989→
   990→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   991→	newRef := plumbing.NewHashReference(refName, newCommitHash)
   992→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   993→		return fmt.Errorf("failed to set branch reference: %w", err)
   994→	}
   995→
   996→	return nil
   997→}
