  1026→// getSessionsBranchTree returns the tree object for the entire/checkpoints/v1 branch.
  1027→// Falls back to origin/entire/checkpoints/v1 if the local branch doesn't exist.
  1028→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
  1029→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1030→	ref, err := s.repo.Reference(refName, true)
  1031→	if err != nil {
  1032→		// Local branch doesn't exist, try remote-tracking branch
  1033→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
  1034→		ref, err = s.repo.Reference(remoteRefName, true)
  1035→		if err != nil {
  1036→			return nil, fmt.Errorf("sessions branch not found: %w", err)
  1037→		}
  1038→	}
  1039→
  1040→	commit, err := s.repo.CommitObject(ref.Hash())
  1041→	if err != nil {
  1042→		return nil, fmt.Errorf("failed to get commit object: %w", err)
  1043→	}
  1044→
  1045→	tree, err := commit.Tree()
  1046→	if err != nil {
  1047→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
  1048→	}
  1049→
  1050→	return tree, nil
  1051→}
