  1053→// CreateBlobFromContent creates a blob object from in-memory content.
  1054→// Exported for use by strategy package (session_test.go)
  1055→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
  1056→	obj := repo.Storer.NewEncodedObject()
  1057→	obj.SetType(plumbing.BlobObject)
  1058→	obj.SetSize(int64(len(content)))
  1059→
  1060→	writer, err := obj.Writer()
  1061→	if err != nil {
  1062→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
  1063→	}
  1064→
  1065→	_, err = writer.Write(content)
  1066→	if err != nil {
  1067→		_ = writer.Close()
  1068→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
  1069→	}
  1070→	if err := writer.Close(); err != nil {
  1071→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
  1072→	}
  1073→
  1074→	hash, err := repo.Storer.SetEncodedObject(obj)
  1075→	if err != nil {
  1076→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
  1077→	}
  1078→	return hash, nil
  1079→}
