  1081→// copyMetadataDir copies all files from a directory to the checkpoint path.
  1082→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
  1083→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
  1084→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
  1085→		if err != nil {
  1086→			return err
  1087→		}
  1088→		if info.IsDir() {
  1089→			return nil
  1090→		}
  1091→
  1092→		// Skip symlinks to prevent reading files outside the metadata directory.
  1093→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
  1094→		// then be captured in the checkpoint and stored in git history.
  1095→		if info.Mode()&os.ModeSymlink != 0 {
  1096→			return nil
  1097→		}
  1098→
  1099→		// Get relative path within metadata dir
  1100→		relPath, err := filepath.Rel(metadataDir, path)
  1101→		if err != nil {
  1102→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
  1103→		}
  1104→
  1105→		// Prevent path traversal via symlinks pointing outside the metadata dir
  1106→		if strings.HasPrefix(relPath, "..") {
  1107→			return fmt.Errorf("path traversal detected: %s", relPath)
  1108→		}
  1109→
  1110→		// Create blob from file with secrets redaction
  1111→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
  1112→		if err != nil {
  1113→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
  1114→		}
  1115→
  1116→		// Store at checkpoint path
  1117→		fullPath := basePath + relPath
  1118→		entries[fullPath] = object.TreeEntry{
  1119→			Name: fullPath,
  1120→			Mode: mode,
  1121→			Hash: blobHash,
  1122→		}
  1123→
  1124→		return nil
  1125→	})
  1126→	if err != nil {
  1127→		return fmt.Errorf("failed to walk metadata directory: %w", err)
  1128→	}
  1129→	return nil
  1130→}
