  1132→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
  1133→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
  1134→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
  1135→	info, err := os.Stat(filePath)
  1136→	if err != nil {
  1137→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
  1138→	}
  1139→
  1140→	mode := filemode.Regular
  1141→	if info.Mode()&0o111 != 0 {
  1142→		mode = filemode.Executable
  1143→	}
  1144→
  1145→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
  1146→	if err != nil {
  1147→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
  1148→	}
  1149→
  1150→	// Skip redaction for binary files — they can't contain text secrets and
  1151→	// running string replacement on them would corrupt the data.
  1152→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
  1153→	if binErr != nil || isBin {
  1154→		hash, err := CreateBlobFromContent(repo, content)
  1155→		if err != nil {
  1156→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
  1157→		}
  1158→		return hash, mode, nil
  1159→	}
  1160→
  1161→	if strings.HasSuffix(treePath, ".jsonl") {
  1162→		content, err = redact.JSONLBytes(content)
  1163→		if err != nil {
  1164→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to redact secrets: %w", err)
  1165→		}
  1166→	} else {
  1167→		content = redact.Bytes(content)
  1168→	}
  1169→
  1170→	hash, err := CreateBlobFromContent(repo, content)
  1171→	if err != nil {
  1172→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
  1173→	}
  1174→	return hash, mode, nil
  1175→}
