  1197→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1198→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1199→// The agentType is used for reassembling chunks in the correct format.
  1200→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1201→	// Collect all transcript-related files
  1202→	var chunkFiles []string
  1203→	var hasBaseFile bool
  1204→
  1205→	for _, entry := range tree.Entries {
  1206→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1207→			hasBaseFile = true
  1208→		}
  1209→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1210→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1211→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1212→			if idx > 0 {
  1213→				chunkFiles = append(chunkFiles, entry.Name)
  1214→			}
  1215→		}
  1216→	}
  1217→
  1218→	// If we have chunk files, read and reassemble them
  1219→	if len(chunkFiles) > 0 {
  1220→		// Sort chunk files by index
  1221→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1222→
  1223→		// Check if base file should be included as chunk 0.
  1224→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1225→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1226→		if hasBaseFile {
  1227→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1228→		}
  1229→
  1230→		var chunks [][]byte
  1231→		for _, chunkFile := range chunkFiles {
  1232→			file, err := tree.File(chunkFile)
  1233→			if err != nil {
  1234→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1235→					slog.String("chunk_file", chunkFile),
  1236→					slog.String("error", err.Error()),
  1237→				)
  1238→				continue
  1239→			}
  1240→			content, err := file.Contents()
  1241→			if err != nil {
  1242→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1243→					slog.String("chunk_file", chunkFile),
  1244→					slog.String("error", err.Error()),
  1245→				)
  1246→				continue
  1247→			}
  1248→			chunks = append(chunks, []byte(content))
  1249→		}
  1250→
  1251→		if len(chunks) > 0 {
  1252→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1253→			if err != nil {
  1254→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1255→			}
  1256→			return result, nil
  1257→		}
  1258→	}
  1259→
  1260→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1261→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1262→		if content, err := file.Contents(); err == nil {
  1263→			return []byte(content), nil
  1264→		}
  1265→	}
  1266→
  1267→	// Try legacy filename
  1268→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1269→		if content, err := file.Contents(); err == nil {
  1270→			return []byte(content), nil
  1271→		}
  1272→	}
  1273→
  1274→	return nil, nil
  1275→}
