  1283→// GetCheckpointAuthor retrieves the author of a checkpoint from the entire/checkpoints/v1 commit history.
  1284→// Returns the author of the commit that introduced this checkpoint's metadata.json file.
  1285→// Returns empty Author if the checkpoint is not found or the sessions branch doesn't exist.
  1286→func (s *GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
  1287→	_ = ctx // Reserved for future use
  1288→
  1289→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1290→	ref, err := s.repo.Reference(refName, true)
  1291→	if err != nil {
  1292→		return Author{}, nil
  1293→	}
  1294→
  1295→	// Path to the checkpoint's metadata file
  1296→	metadataPath := checkpointID.Path() + "/" + paths.MetadataFileName
  1297→
  1298→	// Walk commit history looking for the commit that introduced this file
  1299→	iter, err := s.repo.Log(&git.LogOptions{
  1300→		From:  ref.Hash(),
  1301→		Order: git.LogOrderCommitterTime,
  1302→	})
  1303→	if err != nil {
  1304→		return Author{}, nil
  1305→	}
  1306→	defer iter.Close()
  1307→
  1308→	var author Author
  1309→	var foundCommit *object.Commit
  1310→
  1311→	err = iter.ForEach(func(c *object.Commit) error {
  1312→		tree, treeErr := c.Tree()
  1313→		if treeErr != nil {
  1314→			return nil //nolint:nilerr // Skip commits we can't read, continue searching
  1315→		}
  1316→
  1317→		_, fileErr := tree.File(metadataPath)
  1318→		if fileErr != nil {
  1319→			// File doesn't exist in this commit - we've gone past the creation point
  1320→			if foundCommit != nil {
  1321→				return errStopIteration
  1322→			}
  1323→			return nil
  1324→		}
  1325→
  1326→		// File exists - track it (oldest one with file is the creator)
  1327→		foundCommit = c
  1328→		author = Author{
  1329→			Name:  c.Author.Name,
  1330→			Email: c.Author.Email,
  1331→		}
  1332→		return nil
  1333→	})
  1334→
  1335→	// Ignore errStopIteration - it's just for early exit
  1336→	if err != nil && !errors.Is(err, errStopIteration) {
  1337→		return Author{}, nil
  1338→	}
  1339→
  1340→	return author, nil
  1341→}
